-- Bare Get(…) parameter names — the namespace of the layout symbol {{X}}
-- (Claris: the symbol shows the value of Get(X) at display time). P4 uses
-- it as the validity gate of the displays_symbol edge: only a symbol that
-- names a real Get parameter registers a BuiltinFunction target, so an
-- unknown symbol — which renders LITERALLY at runtime — never invents a
-- catalog object. Localized spellings are part of the set: FileMaker
-- accepts and renders them, and an export may carry either form.
-- Deliberately NOT part of DesignFunctionNames: Get selectors reach the
-- chunk stream only as FunctionRef inside Get(…), never as PluginFunctionRef.
CREATE OR REPLACE TABLE GetParameterNames (
    Function_ID    INTEGER,   -- reference functions.function_id (one row family per parameter)
    Canonical_Name VARCHAR,   -- English parameter name (reference functions.canonical_name)
    Source         VARCHAR,   -- reference lookup source (function_name_lookup.match_source)
    Name           VARCHAR    -- spelling as FileMaker accepts it — canonical English or localized
);
